// 取最近 10 条，生成一张中文日报 HTML
const items = $input.all().map(i => i.json).filter(x => x.title && x.link)
  .sort((a, b) => new Date(b.isoDate || 0) - new Date(a.isoDate || 0))
  .slice(0, 10);
const esc = s => String(s).replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const rows = items.map((x, i) =>
  '<tr><td>' + (i + 1) + '</td><td><a href="' + esc(x.link) + '">' + esc(x.title) + '</a></td><td>' + String(x.isoDate || '').slice(0, 10) + '</td></tr>'
).join('');
const html = '<!doctype html><meta charset="utf-8"><h1>技术日报 ' + new Date().toISOString().slice(0, 10) + '</h1><table border="1" cellpadding="6" style="border-collapse:collapse">' + rows + '</table>';
return [{ json: { count: items.length, tip: 'HTML 已写入 output/daily-digest.html' },
  binary: { data: { data: Buffer.from(html, 'utf8').toString('base64'), mimeType: 'text/html', fileName: 'daily-digest.html' } } }];
